			function onBtnAdd5Click(e){
			    /** 
			     * @type cpr.controls.Button
			     */
			    var btn5 = e.control;
			    
			    /** @type cpr.data.DataSet */
			    var ds = app.lookup("dsList");
			    
			    /** @type cpr.controls.Grid */
			    var grd = app.lookup("grd1");
			    
			    var rowCount = ds.getRowCount();
			    
			    var rowIndex = grd.getSelectedRowIndex();
			    
			    if (rowIndex == -1) {
			        return;
			    }
			    
			    var nextRow = null;
			    if (rowIndex + 1 < rowCount) {
			        nextRow = ds.getRow(nextRowIndexSameLevel(ds, rowIndex));
			    }
			    
			    
			    var row = ds.getRow(rowIndex);
			    
			    var selectedRows = Array();
			    var nextIdx = nextRowIndexSameLevel(ds, rowIndex);
			    var nextIdx2 = nextIdx == ds.getRowCount() ? ds.getRowCount() - 1 : nextRowIndexSameLevel(ds, nextIdx, "small");
			    
			    if (row.getValue("QUSTNB_RELM_MNG_NO") != nextRow.getValue("QUSTNB_RELM_MNG_NO")) {
			        return;    
			    }
			    
			    if (nextRow != null) {
			        var newRowData = row.getRowData();
			        
			        if (nextIdx == ds.getRowCount()) {
			            return;
			        }
			        
			        for (var i = rowIndex; i < nextIdx; i++) {
			            selectedRows.push(ds.getRow(i).getRowData());
			        }
			        
			        for (var i = 0; i < selectedRows.length; i++) {
			            ds.insertRowData(nextIdx2 + i, false, selectedRows[i]);
			        }
			        
			        for (var i = 0; i < selectedRows.length; i++) {
			            ds.deleteRow(rowIndex + i);
			        }
			        
			        ds.commit();
			        grd.selectRows([rowIndex + nextIdx2 - nextIdx]);
			    }
			}

